//! 🛬️ Paged text receives actual original text with retained incremental append and exact closure.
use super::{PagedUtf8,PagedUtf8AppendCursor};
use crate::{NativeDecodeControl,RetirementDemand,ValueError,ErasedSnapshotRetirement,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneRef,RetainedCloneStep,retained_clone_grant_admits}};
use semio_framework_value_native_owned::native_decoding::{NativeReceive,NativeReceiver,OriginalReceivingPrimary,NativeReceivingFailure,OriginalEffectReply,OriginalEffectReplyComplete,owned::{OriginalSourceTurnWitness,NativeAdvanceSelection,native_reply_poll,NativeDefault,NativeDefaultValue,NativeDefaultValueCursor,native_output_demand,native_output_take,native_record_pure_take,tree::{NativeValueSource,invalid,fixed,receipt,nested,child_grant,add_receipt}}};
