/// 🧾️ Records exactly the work a grant-priced step reports under the original effect.
fn record_step(effect:&mut crate::RetainedAllocationEffect<'_>,step:impl FnOnce(RetainedCloneGrant,u64)->RetainedWorkOutcome)->RetainedWorkOutcome{let turn=step(effect.grant(),effect.maximum_work_units());let recorded=u64::try_from(turn.work.saturating_sub(effect.performed_work())).map_err(|_|ValueError::invariant("native grant step work overflow")).and_then(|owed|effect.performed(owed));let result=match recorded{Ok(true)=>turn.result,Ok(false)=>Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native grant step exceeded its original work")),Err(error)=>Err(error)};RetainedWorkOutcome{result,work:turn.work}}
pub struct PagedTextReceiver<I:NativeValueSource+?Sized,const N:usize>{binding:Option<RetainedCloneBinding>,append:PagedUtf8AppendCursor,output:ManuallyDrop<Option<PagedUtf8<N>>>,retirement:RetainedCloneClose,phase:u8,taken:bool,closing:bool,input:std::marker::PhantomData<fn(&I)>}
impl<I:NativeValueSource+?Sized,const N:usize> NativeReceive<I> for PagedUtf8<N>{type Receiver=PagedTextReceiver<I,N>;fn receiver()->Self::Receiver{PagedTextReceiver{binding:None,append:Default::default(),output:ManuallyDrop::new(None),retirement:Default::default(),phase:0,taken:false,closing:false,input:std::marker::PhantomData}}}
impl<I:NativeValueSource+?Sized,const N:usize> NativeReceiver<I,PagedUtf8<N>> for PagedTextReceiver<I,N>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize,_maximum_work_units:u64)->Result<RetirementDemand,ValueError>{if self.closing||self.taken||self.phase==4{return Err(invalid())}input.check_binding(&self.binding)?;match self.phase{0=>Ok(fixed(input.binding_copy_bytes())),1|2=>Ok(fixed(0)),3=>if self.append.complete{Ok(fixed(0))}else{self.append.next_advance_demand(input.get().text()?.as_str(),self.output.as_ref().ok_or_else(invalid)?,body)},_=>Err(invalid())}}
 fn select_advance(&self,input:RetainedCloneRef<'_,I>,_body:usize,maximum_work_units:u64)->Result<NativeAdvanceSelection,ValueError>{if self.closing||self.taken||self.phase==4{return Err(invalid())}Ok(NativeAdvanceSelection::Local{work:if !input.check_binding(&self.binding)?{input.binding_work_demand(&self.binding)?}else if self.phase==3&&!self.append.complete{maximum_work_units.clamp(1,4)}else{1}})}
 fn advance_nested(&mut self,_:RetainedCloneRef<'_,I>,_:&mut NativeDecodeControl<'_>,_:OriginalSourceTurnWitness<'_>,_:usize,_:u64,_:RetainedCloneGrant)->RetainedWorkPoll<RetainedCloneStep,NativeReceivingFailure>{RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Err(invalid().into()),work:0})}
 fn advance_local<'reply>(&mut self,input:RetainedCloneRef<'_,I>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{
  let result:Result<RetainedCloneStep,OriginalReceivingPrimary>=(||{let d=self.demands(input,body,effect.maximum_work_units())?;if !retained_clone_grant_admits(effect.grant(),d){return Ok(RetainedCloneStep::Progress(Default::default()))}
   if self.binding.is_none(){let turn=input.bind(&mut self.binding,effect);return turn.result.map(|p|RetainedCloneStep::Progress(p.unwrap_or_default())).map_err(Into::into)}
   if self.phase==3&&!self.append.complete{let append=&mut self.append;let text=input.get().text()?;let output=self.output.as_mut().ok_or_else(invalid)?;let turn=record_step(effect,|g,_|append.advance(text.as_str(),output,body,g));return turn.result.map_err(Into::into)}
   if !effect.performed(1)?{return Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"native paged text action exceeded its original work").into())}
   match self.phase{0=>self.phase=1,1=>{input.get().text()?;self.phase=2;},2=>{*self.output=Some(PagedUtf8::new());self.phase=3;},3=>self.phase=4,_=>return Err(invalid().into())}
   Ok(if self.phase==4{RetainedCloneStep::Complete(receipt(d))}else{RetainedCloneStep::Progress(receipt(d))})})();
  Ok(reply.complete(result))
 }
 fn output_ready(&self)->bool{self.phase==4&&!self.closing&&!self.taken}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid())}native_output_demand::<PagedUtf8<N>>(size_of::<bool>())}
 fn take_work_demand(&self)->Result<u64,ValueError>{self.take_demand().map(|_|1)}
 fn take<'reply>(&mut self,output:&mut Option<PagedUtf8<N>>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{if !self.output_ready(){return Ok(reply.complete(Err(invalid().into())))}let turn=native_output_take(&mut self.output,output,size_of::<bool>(),effect);if matches!(&turn,RetainedWorkPoll::Complete(RetainedWorkOutcome{result:Ok(RetainedCloneStep::Complete(_)),..})){self.taken=true}native_record_pure_take(turn,reply)}
 fn advance_pending(&self)->bool{false}
 fn is_closing(&self)->bool{self.closing}
 fn begin_close_demand(&self)->Result<RetirementDemand,ValueError>{Ok(if self.closing{Default::default()}else{fixed(size_of::<bool>())})}
 fn begin_close_work_demand(&self)->Result<u64,ValueError>{Ok(u64::from(!self.closing))}
 fn begin_close_into<'reply>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>,ValueError>{if self.closing{return Ok(reply.complete(Ok(RetainedCloneStep::Complete(Default::default()))))}let d=fixed(size_of::<bool>());if !retained_clone_grant_admits(effect.grant(),d)||effect.remaining_work_units()?<1{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"paged text close start exceeded its work authority").into())))}self.append.begin_close();self.closing=true;Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(d)))))}
 fn recover_begin_close_into<'reply>(&mut self,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>,ValueError>{self.begin_close_into(effect,reply)}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if !self.append.terminal_is_empty(){return self.append.next_demand(body)}if !self.retirement.is_empty()||self.output.is_some(){return self.retirement.next_owner_demands::<PagedUtf8<N>>(self.output.is_some(),&None,body)}RetainedCloneBinding::close_demand(&self.binding,body)}
 fn close_work_demand(&self,body:usize)->Result<u64,ValueError>{if !self.closing{return Err(invalid())}if !self.append.terminal_is_empty(){return self.append.next_computational_work(body)}if !self.retirement.is_empty()||self.output.is_some(){return self.retirement.next_owner_work::<PagedUtf8<N>>(self.output.is_some(),&None,body)}RetainedCloneBinding::close_work_demand(&self.binding,body)}
 fn close_step<'reply>(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>,ValueError>{let poll=self.close_poll(body,effect);Ok(native_reply_poll(poll,reply))}
 fn recover_close_step<'reply>(&mut self,_:usize,_:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>,ValueError>{Ok(reply.pending())}
 fn requires_original_birth(&self)->bool{if !self.append.terminal_is_empty(){return self.append.requires_original_birth()}self.retirement.requires_original_birth()}
 fn close_original_birth_step(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,grant:RetainedCloneGrant)->semio_framework_value::OriginalRetirementPoll{if !self.append.terminal_is_empty(){return self.append.close_original_birth_step(original,grant)}self.retirement.step_original_birth(original,grant)}
 fn requires_original_control(&self)->bool{if !self.append.terminal_is_empty(){return self.append.requires_original_control()}self.retirement.requires_original_control()}
 fn close_original_step<'reply>(&mut self,original:&mut crate::OriginalRetirementCloseLoan<'_>,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>,ValueError>{if self.requires_original_birth(){return Err(ValueError::literal(crate::ValueRefusalKind::UnsupportedOwner,"settle original birth first"))}let poll=if !self.append.terminal_is_empty()&&self.append.requires_original_control(){self.append.close_original_step(original,body,effect)}else if self.append.terminal_is_empty()&&self.retirement.requires_original_control(){self.retirement.step_original(original,body,effect)}else{self.close_poll(body,effect)};Ok(native_reply_poll(poll,reply))}
 fn recover_close_original_step<'reply>(&mut self,_:&mut crate::OriginalRetirementCloseLoan<'_>,_:usize,_:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,semio_framework_value::OriginalRetirementFailure>,ValueError>{Ok(reply.pending())}
 fn terminal_is_empty(&self)->bool{self.append.terminal_is_empty()&&self.output.is_none()&&self.retirement.is_empty()&&self.binding.is_none()}
}
impl<I:NativeValueSource+?Sized,const N:usize> PagedTextReceiver<I,N>{
 fn close_poll(&mut self,body:usize,effect:&mut crate::RetainedAllocationEffect<'_>)->semio_framework_value::OriginalRetirementPoll{let g=effect.grant();let mut work=0;let result:Result<RetainedCloneStep,semio_framework_value::RetirementPollExit>=(||{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if !self.append.terminal_is_empty(){let t=semio_framework_value::RetirementPollExit::settled(self.append.close_step(body,&mut effect.nested(g)))?;work=t.work;return t.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)}if !self.retirement.is_empty(){let t=semio_framework_value::RetirementPollExit::settled(self.retirement.step_granted(body,effect))?;work=t.work;return t.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)}if self.output.is_some(){let t=self.retirement.begin_granted(&mut self.output,effect);work=t.work;return t.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default()))).map_err(Into::into)}let t=semio_framework_value::RetirementPollExit::settled(RetainedCloneBinding::close_one(&mut self.binding,body,effect))?;work=t.work;t.result.map_err(Into::into)})();semio_framework_value::RetirementPollExit::finish(result,work)}
}
impl<I:NativeValueSource+?Sized,const N:usize> Drop for PagedTextReceiver<I,N>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"original paged text receiving requires funded closure")}}



