macro_rules! native_default_methods{($value:expr)=>{
 fn default_demand()->RetirementDemand{fixed(0)}
 fn default_work_demand()->Result<u64,ValueError>{Ok(1)}
 fn admit_default<'reply>(output:&mut Option<Self>,effect:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{if output.is_some(){return Ok(reply.complete(Err(invalid().into())))}let d=Self::default_demand();if !retained_clone_grant_admits(effect.grant(),d)||effect.maximum_work_units()==0{return Ok(reply.complete(Ok(RetainedCloneStep::Progress(Default::default()))))}if !effect.performed(1)?{return Ok(reply.complete(Err(ValueError::literal(crate::ValueRefusalKind::WorkLimit,"paged default exceeded its work authority").into())))}*output=Some($value);Ok(reply.complete(Ok(RetainedCloneStep::Complete(receipt(d)))))}
 fn recover_default<'reply>(_:&mut Option<Self>,_:&mut crate::RetainedAllocationEffect<'_>,reply:OriginalEffectReply<'reply,RetainedCloneStep,OriginalReceivingPrimary>)->Result<OriginalEffectReplyComplete<'reply,RetainedCloneStep,OriginalReceivingPrimary>,ValueError>{Ok(reply.pending())}
};}
macro_rules! native_empty_paged{($($ty:ty),*$(,)?)=>{$(impl<const N:usize> NativeDefaultValue for $ty{native_default_methods!(Self::default());}
impl<const N:usize> NativeDefault for $ty{type Cursor=NativeDefaultValueCursor<Self>;fn default_cursor()->Self::Cursor{NativeDefaultValueCursor::new()}}
)*};}
